-- 20261114174204_agent_promo_daily_cap
--
-- TIER 2: one read-only helper, one settings row, and guarded patches of the
-- two agent promo doors and their allowance preview. No wallet or ledger row
-- is written by this migration.
--
-- OWNER INSTRUCTION, 2026-11-14 11:35 Central: "GO AHEAD AND FULLY BUILD, FIX
-- AND ENHANCE ALL OF THESE ... YOU DECIDE". The item: a daily cap per agent on
-- promo chips (self-sends were already refused by both doors).
--
-- Rules already in force before this migration (read from the installed
-- cores): an agent cannot send promo to itself, only to its own downline, and
-- one downline can receive at most 50 promo chips from all agents combined in
-- any 7 days. Staff (owner, co-owner, admin) are not capped. What was missing
-- is a ceiling on one agent's total: 50 chips each to an unlimited number of
-- downline accounts.
--
-- NEW RULE: an agent (super agent, agent, sub agent) may send at most
-- agent_promo_daily_chips promo chips in any 24 hours, across the promo wallet
-- door (fn_promo_wallet_send_core_20261004) and the promo ticket door
-- (fn_cashier_promo_ticket_send); both doors write the same promo_wallet_send
-- receipt, which is what is summed. Default 250, held in sp_digest_settings so
-- it changes without a migration. 250 is two and a half times the largest day
-- any agent has sent (ChiToWnBaLLn, 100 on Nov 12) and five new players at
-- the full 50-chip downline allowance. Staff stay uncapped, as before. A
-- refused send returns error_code promo_agent_daily_limit with the remaining
-- chips, in the same shape as the existing promo_downline_seven_day_limit.
-- fn_cashier_promo_allowance (the cashier's preview) now caps each member's
-- remaining_chips by the agent's own remaining day, so the cashier input
-- limits itself with no client change, and reports agent_daily.
BEGIN;

INSERT INTO public.sp_digest_settings (key, value, note)
VALUES ('agent_promo_daily_chips', 250,
        'Most promo chips one agent (super agent, agent or sub agent) may send in any 24 hours, promo wallet and promo ticket sends combined; staff are not capped')
ON CONFLICT (key) DO NOTHING;

CREATE OR REPLACE FUNCTION public.fn_ca_agent_promo_daily_allowance(p_club_id uuid, p_agent uuid, p_at timestamptz)
RETURNS jsonb
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH cap AS (SELECT trim_scale(round(public.fn_sp_setting('agent_promo_daily_chips', 250), 2)) AS c),
  sent AS (
    SELECT COALESCE(sum(t.amount), 0) AS s
      FROM public.chip_transactions t
     WHERE t.club_id = p_club_id AND t.from_user_id = p_agent
       AND t.transaction_type = 'promo_wallet_send'
       AND t.metadata ->> 'actor_role' IN ('super_agent', 'agent', 'sub_agent')
       AND t.created_at > p_at - interval '24 hours')
  SELECT jsonb_build_object('limit_chips', cap.c, 'window_hours', 24,
                            'sent_last_24_hours', trim_scale(sent.s),
                            'remaining_chips', trim_scale(greatest(0::numeric, cap.c - sent.s)))
    FROM cap, sent;
$function$;

REVOKE ALL ON FUNCTION public.fn_ca_agent_promo_daily_allowance(uuid, uuid, timestamptz) FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION public.fn_ca_agent_promo_daily_allowance(uuid, uuid, timestamptz) IS
  'Agent promo cap (Dan, 2026-11-14): promo chips one agent sent in the 24 hours before p_at across both promo doors, against agent_promo_daily_chips.';

DO $patch$
DECLARE
  original text; updated text; anchor text;
BEGIN
  anchor := $a$'sent_last_7_days', v_sent, 'remaining_chips', v_remaining);
    end if;
  end if;$a$;

  -- Promo wallet door.
  original := pg_get_functiondef('public.fn_promo_wallet_send_core_20261004(uuid, uuid, numeric, text, text, uuid)'::regprocedure);
  IF (length(original) - length(replace(original, anchor, ''))) / length(anchor) <> 1 THEN
    RAISE EXCEPTION 'promo wallet door predecessor changed: downline limit anchor not found exactly once';
  END IF;
  updated := replace(original, anchor, $n$'sent_last_7_days', v_sent, 'remaining_chips', v_remaining);
    end if;
    -- One agent's own ceiling across both promo doors (Dan, 2026-11-14).
    declare
      v_agent_cap jsonb := public.fn_ca_agent_promo_daily_allowance(p_club_id, v_actor, v_limit_time);
    begin
      if p_amount > (v_agent_cap ->> 'remaining_chips')::numeric then
        return jsonb_build_object('success', false,
          'error', format('Promo Limit: An Agent Can Send Only %s Promo Chips In Any 24 Hours. %s Chips Remain.',
                          v_agent_cap ->> 'limit_chips', v_agent_cap ->> 'remaining_chips'),
          'error_code', 'promo_agent_daily_limit',
          'limit_chips', (v_agent_cap ->> 'limit_chips')::numeric, 'window_hours', 24,
          'sent_last_24_hours', (v_agent_cap ->> 'sent_last_24_hours')::numeric,
          'remaining_chips', (v_agent_cap ->> 'remaining_chips')::numeric);
      end if;
    end;
  end if;$n$);
  EXECUTE updated;

  -- Promo ticket door.
  original := pg_get_functiondef('public.fn_cashier_promo_ticket_send(uuid, uuid, numeric, text)'::regprocedure);
  IF (length(original) - length(replace(original, anchor, ''))) / length(anchor) <> 1 THEN
    RAISE EXCEPTION 'promo ticket door predecessor changed: downline limit anchor not found exactly once';
  END IF;
  updated := replace(original, anchor, $n$'sent_last_7_days', v_sent, 'remaining_chips', v_remaining);
    end if;
    -- One agent's own ceiling across both promo doors (Dan, 2026-11-14).
    declare
      v_agent_cap jsonb := public.fn_ca_agent_promo_daily_allowance(p_club_id, v_me, v_limit_time);
    begin
      if p_value > (v_agent_cap ->> 'remaining_chips')::numeric then
        return jsonb_build_object('success', false,
          'error', format('Promo Limit: An Agent Can Send Only %s Promo Chips In Any 24 Hours. %s Chips Remain.',
                          v_agent_cap ->> 'limit_chips', v_agent_cap ->> 'remaining_chips'),
          'error_code', 'promo_agent_daily_limit',
          'limit_chips', (v_agent_cap ->> 'limit_chips')::numeric, 'window_hours', 24,
          'sent_last_24_hours', (v_agent_cap ->> 'sent_last_24_hours')::numeric,
          'remaining_chips', (v_agent_cap ->> 'remaining_chips')::numeric);
      end if;
    end;
  end if;$n$);
  EXECUTE updated;

  -- Cashier preview: each member's remaining allowance also respects the
  -- agent's own remaining day, and the agent's day is reported.
  original := pg_get_functiondef('public.fn_cashier_promo_allowance(uuid, uuid[])'::regprocedure);
  updated := replace(original,
    $o$'remaining_chips', greatest(0::numeric, 50::numeric - s.sent))), '[]'::jsonb)$o$,
    $n$'remaining_chips', least(greatest(0::numeric, 50::numeric - s.sent),
             (public.fn_ca_agent_promo_daily_allowance(p_club_id, v_me, v_now) ->> 'remaining_chips')::numeric))), '[]'::jsonb)$n$);
  IF updated = original THEN RAISE EXCEPTION 'promo allowance predecessor changed: remaining_chips not found'; END IF;
  original := updated;
  updated := replace(original,
    $o$'limit_chips', 50, 'window_hours', 168, 'allowances', v_rows);$o$,
    $n$'limit_chips', 50, 'window_hours', 168, 'allowances', v_rows,
    'agent_daily', public.fn_ca_agent_promo_daily_allowance(p_club_id, v_me, v_now));$n$);
  IF updated = original THEN RAISE EXCEPTION 'promo allowance predecessor changed: capped result not found'; END IF;
  EXECUTE updated;
END $patch$;

DO $verify$
DECLARE r jsonb;
BEGIN
  IF position('promo_agent_daily_limit' IN pg_get_functiondef('public.fn_promo_wallet_send_core_20261004(uuid, uuid, numeric, text, text, uuid)'::regprocedure)) = 0
     OR position('promo_agent_daily_limit' IN pg_get_functiondef('public.fn_cashier_promo_ticket_send(uuid, uuid, numeric, text)'::regprocedure)) = 0
     OR position('agent_daily' IN pg_get_functiondef('public.fn_cashier_promo_allowance(uuid, uuid[])'::regprocedure)) = 0 THEN
    RAISE EXCEPTION 'agent promo cap is not wired into every promo door';
  END IF;
  IF has_function_privilege('anon', 'public.fn_ca_agent_promo_daily_allowance(uuid, uuid, timestamptz)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.fn_ca_agent_promo_daily_allowance(uuid, uuid, timestamptz)', 'EXECUTE') THEN
    RAISE EXCEPTION 'allowance helper is executable by a client role';
  END IF;
  -- twin2983 (KINGS CLUB super agent) read against the cap.
  r := public.fn_ca_agent_promo_daily_allowance('a41434bb-8d0c-400a-8f0d-e8b3d65afed4', '2e8073d8-ada2-4576-a879-02b9532a858e', clock_timestamp());
  IF (r ->> 'limit_chips')::numeric <> public.fn_sp_setting('agent_promo_daily_chips', 250) THEN
    RAISE EXCEPTION 'helper does not read the configured cap: %', r;
  END IF;
END $verify$;

COMMIT;

-- 20261114174518_cashier_history_names_the_union_or_club_that_sent
--
-- TIER 2: one read-only naming helper and guarded patches of the three
-- cashier history feeds and the cashier statement. No wallet, ledger or
-- transaction row is written by this migration.
--
-- WHY: Dan, 2026-11-14 10:13 Central, on a receipt reading "TRANSFER: A Member
-- To MeepMeep", "ENTRY: Promo Disbursement": "WHAT WAS THIS, AND WHY WAS IT
-- RANDOMLY SENT TO THIS PLAYER?" It was the Midway Union's Welcome Back Chips
-- (chip_transactions 07ddbdc4-701f-47cb-9fd4-7d89b9c62a91). The cashier
-- history feeds name the sender from the sender's profile; a union or club
-- payment has no sender profile (from_user_id is NULL), so from_name came back
-- NULL and the Club Arena client printed its fallback, "A Member". 11:35
-- Central: "GO AHEAD AND FULLY BUILD, FIX AND ENHANCE ALL OF THESE".
--
-- WHAT CHANGES (names only, display data):
--   fn_ca_transaction_party_name(side, type, metadata, club, notes) names the
--   non-person party of a chip transaction:
--     * a promo disbursement's sender: the union or club named by its
--       source_id, with the program from its note, e.g.
--       "Midway Union (Welcome Back Chips)";
--     * a union send's sender: the union;
--     * any other row without a sender profile: the club itself (club bank
--       sends a viewer may not attribute to a staff member keep that privacy:
--       the club is named, never the staff member);
--     * a promo disbursement or union promo landing in a club: that club.
--   fn_cashier_history_feed, fn_cashier_history_page and
--   fn_cashier_transaction_history fall back to it where from_name / to_name
--   were NULL; fn_cashier_statement_rows falls back to the union or club name
--   for a non-profile from/to id. Every person-named row is unchanged.
BEGIN;

CREATE OR REPLACE FUNCTION public.fn_ca_transaction_party_name(p_side text, p_type text, p_metadata jsonb, p_club_id uuid, p_notes text)
RETURNS text
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH base AS (
    SELECT CASE
      WHEN p_side = 'from' AND p_type = 'promo_disbursement' THEN
        CASE WHEN p_metadata ->> 'source_kind' = 'union'
             THEN (SELECT u.name FROM public.unions u WHERE u.id::text = p_metadata ->> 'source_id')
             ELSE (SELECT c.name FROM public.clubs c WHERE c.id::text = p_metadata ->> 'source_id') END
      WHEN p_side = 'from' AND p_type IN ('union_promo_send', 'union_promo_to_club', 'union_member_send', 'union_transfer',
                                          'union_transfer_reversal', 'union_clawback', 'union_promo_clawback') THEN
        (SELECT u.name FROM public.unions u WHERE u.id::text = COALESCE(p_metadata ->> 'union_id', p_metadata ->> 'source_id'))
      WHEN p_side = 'to' AND p_type = 'promo_disbursement' AND p_metadata ->> 'target_kind' = 'club' THEN
        (SELECT c.name FROM public.clubs c WHERE c.id::text = p_metadata ->> 'target_id')
      WHEN p_side = 'to' AND p_type = 'union_promo_to_club' THEN
        (SELECT c.name FROM public.clubs c WHERE c.id = p_club_id)
      WHEN p_side = 'from' THEN
        (SELECT c.name FROM public.clubs c WHERE c.id = p_club_id)
    END AS name
  ), program AS (
    SELECT NULLIF(btrim(split_part(split_part(COALESCE(p_notes, ''), ' - ', 1), ':', 1)), '') AS p
  )
  SELECT CASE
           WHEN base.name IS NULL THEN NULL
           WHEN p_side = 'from' AND p_type = 'promo_disbursement' AND program.p IS NOT NULL
                AND program.p <> 'Promo Disbursement' AND program.p NOT ILIKE 'promo disbursed%'
             THEN base.name || ' (' || program.p || ')'
           ELSE base.name
         END
    FROM base, program;
$function$;

REVOKE ALL ON FUNCTION public.fn_ca_transaction_party_name(text, text, jsonb, uuid, text) FROM PUBLIC, anon, authenticated;

COMMENT ON FUNCTION public.fn_ca_transaction_party_name(text, text, jsonb, uuid, text) IS
  'Names the union or club party of a chip transaction with no person on that side, e.g. "Midway Union (Welcome Back Chips)" (Dan, 2026-11-14: receipts said "A Member").';

DO $patch$
DECLARE
  fn text;
  original text;
  updated text;
  from_old text := $o$THEN public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name) END,$o$;
  from_new text := $n$THEN public.fn_arena_name(pf.alias, pf.username, pf.display_name, pf.first_name, pf.last_name, pf.full_name)
                ELSE public.fn_ca_transaction_party_name('from', ct.transaction_type, ct.metadata, ct.club_id, ct.notes) END,$n$;
  to_old text := $o$CASE WHEN pt.id IS NOT NULL THEN public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name) END$o$;
  to_new text := $n$CASE WHEN pt.id IS NOT NULL THEN public.fn_arena_name(pt.alias, pt.username, pt.display_name, pt.first_name, pt.last_name, pt.full_name)
                ELSE public.fn_ca_transaction_party_name('to', ct.transaction_type, ct.metadata, ct.club_id, ct.notes) END$n$;
BEGIN
  FOREACH fn IN ARRAY ARRAY[
    'public.fn_cashier_history_feed(uuid, text, text, timestamptz, timestamptz, uuid, text, timestamptz, uuid, integer)',
    'public.fn_cashier_history_page(uuid, text, text, timestamptz, timestamptz, integer, integer)',
    'public.fn_cashier_transaction_history(uuid, text, integer, integer)'] LOOP
    original := pg_get_functiondef(fn::regprocedure);
    IF position(from_old IN original) = 0 OR position(to_old IN original) = 0 THEN
      RAISE EXCEPTION '% predecessor changed: name expressions not found', fn;
    END IF;
    updated := replace(replace(original, from_old, from_new), to_old, to_new);
    EXECUTE updated;
  END LOOP;

  original := pg_get_functiondef('public.fn_cashier_statement_rows(uuid, uuid, text, timestamptz, timestamptz, jsonb, timestamptz, text, uuid, integer)'::regprocedure);
  updated := replace(original,
    $o$ELSE p.from_ledger_label END AS from_label$o$,
    $n$ELSE COALESCE(p.from_ledger_label,
                               (SELECT un.name FROM public.unions un WHERE un.id = p.from_id),
                               (SELECT cb.name FROM public.clubs cb WHERE cb.id = p.from_id)) END AS from_label$n$);
  IF updated = original THEN RAISE EXCEPTION 'statement predecessor changed: from_label not found'; END IF;
  original := updated;
  updated := replace(original,
    $o$ELSE p.to_ledger_label END AS to_label$o$,
    $n$ELSE COALESCE(p.to_ledger_label,
                               (SELECT un.name FROM public.unions un WHERE un.id = p.to_id),
                               (SELECT cb.name FROM public.clubs cb WHERE cb.id = p.to_id)) END AS to_label$n$);
  IF updated = original THEN RAISE EXCEPTION 'statement predecessor changed: to_label not found'; END IF;
  EXECUTE updated;
END $patch$;

DO $verify$
DECLARE n text;
BEGIN
  SELECT public.fn_ca_transaction_party_name('from', ct.transaction_type, ct.metadata, ct.club_id, ct.notes) INTO n
    FROM public.chip_transactions ct WHERE ct.id = '07ddbdc4-701f-47cb-9fd4-7d89b9c62a91';
  IF n IS DISTINCT FROM 'Midway Union (Welcome Back Chips)' THEN
    RAISE EXCEPTION 'MeepMeep''s receipt sender reads %, expected Midway Union (Welcome Back Chips)', n;
  END IF;
  IF has_function_privilege('anon', 'public.fn_ca_transaction_party_name(text, text, jsonb, uuid, text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.fn_ca_transaction_party_name(text, text, jsonb, uuid, text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'naming helper is executable by a client role';
  END IF;
  IF NOT has_function_privilege('authenticated', 'public.fn_cashier_history_feed(uuid, text, text, timestamptz, timestamptz, uuid, text, timestamptz, uuid, integer)', 'EXECUTE') THEN
    RAISE EXCEPTION 'history feed lost its authenticated grant';
  END IF;
END $verify$;

COMMIT;
